window.OW_JOURNAL = {"meta":{"saveDate":"2026-10-04 11:55","loopCount":52,"fullTimeloops":12,"burnedMarshmallows":11,"perfectMarshmallows":0,"factCount":245},"entries":[{"astro":"BRITTLE_HOLLOW","id":"BH_RIEBECK","name":"Campement de Riébeck","parent":null,"state":"done","firstOrder":11,"facts":[{"id":"BH_RIEBECK_R1","rumor":true,"order":11,"unread":false,"text":"Riébeck a voulu se rendre sur Cravité pour en apprendre plus sur ce que les Nomaï faisaient au pôle Sud."},{"id":"BH_RIEBECK_X1","rumor":false,"order":17,"unread":false,"text":"Riébeck a établi son campement au fond de la croisée des chemins. L\u0027excitation de se trouver au beau milieu d\u0027un trésor historique nomaï de cette importance le disputait à la terreur que lui inspirait le trou noir."},{"id":"BH_RIEBECK_X2","rumor":false,"order":20,"unread":false,"text":"Âtrebois ne compte aucun autre archéologue que Riébeck, qui a surmonté sa peur de l\u0027espace pour partir étudier la mine de culture nomaï que renferme Cravité."},{"id":"BH_RIEBECK_R4","rumor":true,"order":21,"unread":false,"text":"Riébeck a atteint la croisée des chemins et a continué en contrebas en quête d\u0027oxygène."},{"id":"BH_RIEBECK_R3","rumor":true,"order":22,"unread":false,"text":"Riébeck a découvert un ancien chemin nomaï près de son campement, sur l\u0027équateur. Ce passage part du bâtiment en ruine envahi d\u0027arbres."},{"id":"BH_RIEBECK_R2","rumor":true,"order":48,"unread":false,"text":"Riébeck a atterri près du grand dôme au pôle Sud. Comme la porte d\u0027entrée était cassée, Riébeck a décidé de se rendre aux ruines de l\u0027équateur, au nord, pour trouver un moyen de descendre sous la surface."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_GRAVITY_CANNON","name":"Canon gravitationnel","parent":null,"state":"done","firstOrder":24,"facts":[{"id":"BH_GRAVITY_CANNON_X2","rumor":false,"order":24,"unread":false,"text":"J\u0027ai rappelé une navette nomaï de la Lune quantique."},{"id":"BH_GRAVITY_CANNON_X1","rumor":false,"order":25,"unread":false,"text":"Une gigantesque structure cylindrique qui génère un puissant champ gravitationnel vertical."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_QUANTUM_RESEARCH_TOWER","name":"Tour du savoir quantique","parent":null,"state":"done","firstOrder":15,"facts":[{"id":"BH_QUANTUM_RESEARCH_TOWER_R1","rumor":true,"order":15,"unread":false,"text":"Cette tour (située sur l\u0027équateur de Cravité) renfermait un précieux savoir pour les Nomaï qui entreprenaient leur premier pèlerinage vers la Lune quantique."},{"id":"BH_QUANTUM_RESEARCH_TOWER_X2","rumor":false,"order":199,"unread":false,"text":"Le pèlerinage vers la Lune quantique représentait un voyage d\u0027une grande importance pour les Nomaï."},{"id":"BH_QUANTUM_RESEARCH_TOWER_X3","rumor":false,"order":200,"unread":false,"text":"Lorsque les deux groupes de Nomaï, échoués respectivement sur la Sablière rouge et Cravité, furent enfin réunis, la recherche et l\u0027exploration de la Lune quantique devinrent leur objectif commun."},{"id":"BH_QUANTUM_RESEARCH_TOWER_X1","rumor":false,"order":204,"unread":false,"text":"Les Nomaï édifièrent un autel sur la Lune quantique afin d\u0027aider les pèlerins à atteindre son sixième emplacement. \"Retiens bien cette dernière règle : pour que tu puisses accéder au sixième emplacement, l\u0027autel doit se trouver au pôle Nord de la Lune.\""}]},{"astro":"BRITTLE_HOLLOW","id":"BH_QUANTUM_SHARD","name":"Roc quantique","parent":"BH_QUANTUM_RESEARCH_TOWER","state":"done","firstOrder":16,"facts":[{"id":"BH_QUANTUM_SHARD_R1","rumor":true,"order":16,"unread":false,"text":"Les Nomaï constatèrent la présence d\u0027un étrange fragment de roche qui semblait se déplacer lorsque personne ne le regardait."},{"id":"BH_QUANTUM_SHARD_X1","rumor":false,"order":37,"unread":false,"text":"Un étrange fragment de roche qui se déplace lorsque personne ne le regarde. Les Nomaï parvinrent à la conclusion que ce fragment causait le comportement quantique de tout ce qui se trouve dans ces bois."},{"id":"BH_QUANTUM_SHARD_X3","rumor":false,"order":38,"unread":false,"text":"Ce fragment émet le même signal que la Lune quantique."},{"id":"BH_QUANTUM_SHARD_X2","rumor":false,"order":42,"unread":false,"text":"Les Nomaï avancèrent l\u0027hypothèse que ce fragment était en fait un morceau de la Lune quantique."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_WARP_RECEIVER","name":"Glacier nord","parent":null,"state":"done","firstOrder":27,"facts":[{"id":"BH_WARP_RECEIVER_X1","rumor":false,"order":27,"unread":false,"text":"Le pôle Nord de Cravité est couvert de neige et de glace. On trouve à sa surface une ruine nomaï à la forme particulière."},{"id":"BH_WARP_RECEIVER_X2","rumor":false,"order":28,"unread":false,"text":"Les Nomaï pouvaient employer la distorsion pour voyager depuis la station du trou blanc jusqu\u0027ici. C\u0027est là qu\u0027ils ont reconstitué la technologie de distorsion."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_ESCAPE_POD","name":"Capsule de sauvetage 1","parent":null,"state":"done","firstOrder":183,"facts":[{"id":"BH_ESCAPE_POD_X1","rumor":false,"order":183,"unread":false,"text":"L\u0027une des trois capsules de sauvetage nomaï qui s\u0027écrasèrent dans notre système solaire."},{"id":"BH_ESCAPE_POD_X2","rumor":false,"order":185,"unread":false,"text":"Ces trois capsules de sauvetage provenaient d\u0027une chose appelée le Vaisseau, qui avait subi d\u0027importants dégâts."},{"id":"BH_ESCAPE_POD_R1","rumor":true,"order":193,"unread":false,"text":"L\u0027une des trois capsules de sauvetage nomaï atterrit quelque part sur Cravité."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_OLD_SETTLEMENT","name":"Ancienne colonie","parent":null,"state":"done","firstOrder":184,"facts":[{"id":"BH_OLD_SETTLEMENT_R1","rumor":true,"order":184,"unread":false,"text":"Les survivants nomaï échoués sur Cravité descendirent le long du gouffre et trouvèrent refuge sous la surface."},{"id":"BH_OLD_SETTLEMENT_X1","rumor":false,"order":186,"unread":false,"text":"Les Nomaï établirent une colonie provisoire sous leur capsule de sauvetage."},{"id":"BH_OLD_SETTLEMENT_X4","rumor":false,"order":187,"unread":false,"text":"Inquiets quant à la stabilité de leur colonie, les Nomaï décidèrent d\u0027aller s\u0027installer ailleurs."},{"id":"BH_OLD_SETTLEMENT_X2","rumor":false,"order":189,"unread":false,"text":"Les Nomaï unirent leurs efforts pour retrouver la trace d\u0027un signal en forme d\u0027œil qu\u0027ils avaient détecté à bord du Vaisseau."},{"id":"BH_OLD_SETTLEMENT_X3","rumor":false,"order":190,"unread":false,"text":"Le signal était apparemment plus ancien que l\u0027univers lui-même. Les Nomaï le baptisèrent \"l\u0027Œil de l\u0027univers\"."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_MURAL_3","name":"Peinture murale (panneau 3)","parent":"BH_OLD_SETTLEMENT","state":"done","firstOrder":191,"facts":[{"id":"BH_MURAL_3_X1","rumor":false,"order":191,"unread":false,"text":"Une peinture murale représentant les trois capsules de sauvetage quittant le Vaisseau nomaï."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_MURAL_2","name":"Peinture murale (panneau 2)","parent":"BH_OLD_SETTLEMENT","state":"done","firstOrder":197,"facts":[{"id":"BH_MURAL_2_X1","rumor":false,"order":197,"unread":false,"text":"Une peinture murale représentant le Vaisseau nomaï pris au piège sur Sombronces."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_MURAL_1","name":"Peinture murale (panneau 1)","parent":"BH_OLD_SETTLEMENT","state":"done","firstOrder":196,"facts":[{"id":"BH_MURAL_1_X1","rumor":false,"order":196,"unread":false,"text":"Une peinture murale représentant le Vaisseau nomaï détectant un signal."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_HANGING_CITY","name":"Cité suspendue","parent":null,"state":"done","firstOrder":18,"facts":[{"id":"BH_HANGING_CITY_R2","rumor":true,"order":18,"unread":false,"text":"Juste au nord du campement de Riébeck s\u0027étend une gigantesque cité nomaï."},{"id":"BH_HANGING_CITY_X1","rumor":false,"order":30,"unread":false,"text":"Une cité nomaï suspendue sous le glacier nord de Cravité. La cité est construite selon une structure verticale et se compose de quatre secteurs."},{"id":"BH_HANGING_CITY_X3","rumor":false,"order":32,"unread":false,"text":"Les Nomaï réfléchirent à la meilleure manière de concevoir le générateur de distorsion puissant et hautement avancé dont ils avaient besoin pour le projet Sablière noire."},{"id":"BH_HANGING_CITY_X2","rumor":false,"order":36,"unread":false,"text":"J\u0027ai trouvé dans le secteur de l\u0027eau de fonte un interrupteur qui commande l\u0027accès à la forge du trou noir."},{"id":"BH_HANGING_CITY_X4","rumor":false,"order":43,"unread":false,"text":"Les Nomaï vinrent dans ce système solaire en quête d\u0027un signal émis par une entité plus vieille que l\u0027univers lui-même. Ils baptisèrent la source de ce signal \"l\u0027Œil de l\u0027univers\"."},{"id":"BH_HANGING_CITY_R1","rumor":true,"order":188,"unread":false,"text":"Les Nomaï décidèrent de quitter l\u0027ancienne colonie pour se rendre au glacier nord. Ils se servirent de cristaux gravitationnels pour créer un chemin stable sous la surface."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_BLACK_HOLE_FORGE","name":"Forge du trou noir","parent":null,"state":"rumor","firstOrder":31,"facts":[{"id":"BH_BLACK_HOLE_FORGE_R2","rumor":true,"order":31,"unread":false,"text":"Le secteur de la forge du trou noir domine la Cité suspendue."},{"id":"BH_BLACK_HOLE_FORGE_R3","rumor":true,"order":33,"unread":false,"text":"Une Nomaï du nom de Poke envisagea de concevoir un nouveau générateur de distorsion avancé dans la forge du trou noir."},{"id":"BH_BLACK_HOLE_FORGE_R1","rumor":true,"order":37,"unread":false,"text":"La forge du trou noir est suspendue sous la cité. J\u0027ai trouvé dans le secteur de l\u0027eau de fonte un interrupteur qui commande l\u0027accès à la forge du trou noir."},{"id":"BH_BLACK_HOLE_FORGE_R4","rumor":true,"order":103,"unread":false,"text":"Les Nomaï façonnaient des générateurs de distorsion à la forge du trou noir avant de les envoyer sur la Sablière noire."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_OBSERVATORY","name":"Observatoire sud","parent":null,"state":"done","firstOrder":10,"facts":[{"id":"BH_OBSERVATORY_R1","rumor":true,"order":10,"unread":false,"text":"Les Nomaï décidèrent de construire un traceur oculaire plus grand et sophistiqué au pôle Sud de Cravité."},{"id":"BH_OBSERVATORY_R3","rumor":true,"order":19,"unread":false,"text":"Riébeck affirme (en connaissance de cause) qu\u0027il est impossible d\u0027accéder à l\u0027observatoire depuis la surface, mais qu\u0027il doit exister un chemin souterrain."},{"id":"BH_OBSERVATORY_R4","rumor":true,"order":49,"unread":false,"text":"Il y a à la surface une porte permettant d\u0027accéder à l\u0027observatoire, mais elle est cassée."},{"id":"BH_OBSERVATORY_X1","rumor":false,"order":50,"unread":false,"text":"Le traceur plus sensible conçu par les Nomaï dans cet observatoire se révéla incapable de détecter la moindre trace du signal de l\u0027Œil."},{"id":"BH_OBSERVATORY_X2","rumor":false,"order":51,"unread":false,"text":"D\u0027après ce qu\u0027ils savaient de la Lune quantique, les Nomaï pensaient que l\u0027Œil décrivait une orbite lointaine autour du soleil."},{"id":"BH_OBSERVATORY_X3","rumor":false,"order":52,"unread":false,"text":"Les Nomaï décidèrent de cesser leur recherche du signal de l\u0027Œil pour tenter de le trouver visuellement en envoyant une sonde dans l\u0027espace."},{"id":"BH_OBSERVATORY_X4","rumor":false,"order":53,"unread":false,"text":"Ils craignaient que la probabilité de lancer une sonde dans la bonne direction ne soit dérisoire."},{"id":"BH_OBSERVATORY_R2","rumor":true,"order":74,"unread":false,"text":"Il existe sous la surface de Cravité deux chemins menant à l\u0027observatoire. L\u0027un d\u0027eux part du canon gravitationnel, l\u0027autre de la Tour du savoir quantique."}]},{"astro":"BRITTLE_HOLLOW","id":"BH_TORNADO_SIMULATION","name":"Simulation de la tornade","parent":"BH_OBSERVATORY","state":"done","firstOrder":46,"facts":[{"id":"BH_TORNADO_SIMULATION_X1","rumor":false,"order":46,"unread":false,"text":"La plupart des cyclones de Léviathe effectuent une rotation horaire. Ce sont de ces cyclones que les Nomaï se servaient pour mettre des composés en orbites."},{"id":"BH_TORNADO_SIMULATION_X2","rumor":false,"order":47,"unread":false,"text":"Il existe une variété de cyclones plus rares avec un sens de rotation inversé qui emporte les objets sous l\u0027eau et sous les courants."},{"id":"BH_TORNADO_SIMULATION_R1","rumor":true,"order":73,"unread":false,"text":"Le Nomaï travaillant à l\u0027observatoire sud réalisa une modélisation de Léviathe qui révéla de quelle façon un objet pouvait se retrouver sous le puissant courant océanique."}]},{"astro":"WHITE_HOLE","id":"WHITE_HOLE_STATION","name":"Station du trou blanc","parent":null,"state":"done","firstOrder":23,"facts":[{"id":"WHS_X4","rumor":false,"order":23,"unread":false,"text":"Chacune des tours de distorsion nomaï est assignée à un corps astral spécifique."},{"id":"WHS_X1","rumor":false,"order":24,"unread":false,"text":"Pour utiliser une tour, vous devez vous tenir au milieu de la plateforme de distorsion pendant son alignement avec son corps astral correspondant (l\u0027alignement se fait lorsque le corps astral est juste au-dessus de vous)."},{"id":"WHS_R1","rumor":true,"order":26,"unread":false,"text":"Il existe une station du trou blanc de l\u0027autre côté du trou noir de Cravité."},{"id":"WHS_R2","rumor":true,"order":29,"unread":false,"text":"Plusieurs Nomaï revinrent à la station pour étudier un relevé qui semblait aller à l\u0027encontre du principe de causalité."},{"id":"WHS_R4","rumor":true,"order":104,"unread":false,"text":"La station du trou blanc servit de modèle pour les tours de la Sablière noire."},{"id":"WHS_R3","rumor":true,"order":122,"unread":false,"text":"Les expériences conduites au laboratoire des hautes énergies reposaient sur les découvertes extraordinaires réalisées à la station du trou blanc."},{"id":"WHS_X2","rumor":false,"order":124,"unread":false,"text":"Les Nomaï ont constaté un phénomène étrange : des objets envoyés par distorsion semblaient arriver au récepteur de Cravité légèrement avant leur départ de la station du trou blanc."},{"id":"WHS_X3","rumor":false,"order":125,"unread":false,"text":"L\u0027intervalle de temps négatif observé entre l\u0027arrivée et le départ d\u0027un objet était incroyablement court (approximativement un cent millième de seconde). Les Nomaï n\u0027étaient même pas certains que leur équipement fût capable de mesurer le temps à une si petite échelle."}]},{"astro":"DARK_BRAMBLE","id":"DB_FELDSPAR","name":"Campement de Feldspath","parent":null,"state":"done","firstOrder":63,"facts":[{"id":"DB_FELDSPAR_R1","rumor":true,"order":63,"unread":false,"text":"Feldspath a voulu se rendre sur Sombronces après avoir atteint le cœur de Léviathe."},{"id":"DB_FELDSPAR_R2","rumor":true,"order":132,"unread":false,"text":"Quand j\u0027envoie mon guetteur à l\u0027intérieur de la graine qui s\u0027est écrasée sur Âtrebois, il se retrouve dans un endroit envahi par la brume et les ronces."},{"id":"DB_FELDSPAR_X1","rumor":false,"order":151,"unread":false,"text":"Feldspath est en vie ! Suite au crash de sa navette, Feldspath a établi son campement à l\u0027intérieur du squelette d\u0027un gigantesque cœlacanthe."},{"id":"DB_FELDSPAR_X2","rumor":false,"order":152,"unread":false,"text":"Selon Feldspath, les relevés indiquant que mon guetteur se trouve à deux endroits en même temps ne sont pas erronés. À l\u0027en croire, l\u0027espace fonctionne différemment à l\u0027intérieur de Sombronces."},{"id":"DB_FELDSPAR_X3","rumor":false,"order":154,"unread":false,"text":"Feldspath n\u0027a pas l\u0027air particulièrement avide de retrouver la civilisation et apprécie le calme et le silence (relatifs) de la planète."}]},{"astro":"DARK_BRAMBLE","id":"DB_FROZEN_JELLYFISH","name":"Méduse gelée","parent":null,"state":"done","firstOrder":153,"facts":[{"id":"DB_FROZEN_JELLYFISH_R1","rumor":true,"order":153,"unread":false,"text":"Feldspath a laissé entendre que la liane creuse dans laquelle son vaisseau s\u0027est écrasé renferme à son extrémité un secret pour atteindre le cœur de Léviathe. Pour retrouver le vaisseau de Feldspath, je dois suivre le squelette de cœlacanthe jusqu\u0027à sa queue et chercher une lueur vacillante dans la brume."},{"id":"DB_FROZEN_JELLYFISH_X1","rumor":false,"order":155,"unread":false,"text":"Feldspath a consigné ses tentatives de manger cette gigantesque méduse congelée. L\u0027épiderme était épais et caoutchouteux, peut-être pour protéger les entrailles de la méduse des décharges électriques."},{"id":"DB_FROZEN_JELLYFISH_X2","rumor":false,"order":156,"unread":false,"text":"Feldspath a décidé d\u0027explorer la cavité interne de la méduse pour voir si elle avait meilleur goût de l\u0027intérieur."},{"id":"DB_FROZEN_JELLYFISH_X3","rumor":false,"order":157,"unread":false,"text":"Après avoir goûté l\u0027intérieur de la méduse, Feldspath est parvenu à la conclusion que ces organismes ne servent qu\u0027à se protéger des courants électriques."}]},{"astro":"DARK_BRAMBLE","id":"DB_ESCAPE_POD","name":"Capsule de sauvetage 3","parent":null,"state":"done","firstOrder":138,"facts":[{"id":"DB_ESCAPE_POD_X1","rumor":false,"order":138,"unread":false,"text":"L\u0027une des trois capsules de sauvetage nomaï qui s\u0027écrasèrent dans notre système solaire."},{"id":"DB_ESCAPE_POD_X2","rumor":false,"order":139,"unread":false,"text":"Ces trois capsules de sauvetage provenaient d\u0027une chose appelée le Vaisseau, qui avait subi d\u0027importants dégâts."},{"id":"DB_ESCAPE_POD_X3","rumor":false,"order":141,"unread":false,"text":"Les survivants de la capsule de sauvetage 3 détectèrent deux balises distinctes provenant du Vaisseau, comme s\u0027il se trouvait à deux endroits à la fois."},{"id":"DB_ESCAPE_POD_R1","rumor":true,"order":194,"unread":false,"text":"L\u0027une des trois capsules de sauvetage nomaï ne repartit jamais de Sombronces."}]},{"astro":"DARK_BRAMBLE","id":"DB_NOMAI_GRAVE","name":"Tombe nomaï","parent":null,"state":"done","firstOrder":140,"facts":[{"id":"DB_NOMAI_GRAVE_R1","rumor":true,"order":140,"unread":false,"text":"Les survivants de la capsule de sauvetage 3 abandonnèrent l\u0027épave et tentèrent de retourner au Vaisseau."},{"id":"DB_NOMAI_GRAVE_X1","rumor":false,"order":142,"unread":false,"text":"Les survivants de la capsule de sauvetage 3 suivirent l\u0027une des deux balises du Vaisseau jusqu\u0027à une petite graine de Sombronces, mais ne purent aller plus loin."},{"id":"DB_NOMAI_GRAVE_R2","rumor":true,"order":142,"unread":false,"text":"Les survivants décidèrent de suivre la plus proche des deux balises du Vaisseau en raison de la quantité d\u0027oxygène limitée dont ils disposaient. Ils avaient l\u0027intention de laisser des lumières derrière eux dans l\u0027éventualité où quelqu\u0027un aurait entendu leur signal de détresse."},{"id":"DB_NOMAI_GRAVE_X2","rumor":false,"order":143,"unread":false,"text":"Les Nomaï parvenaient à entendre le faible signal émis par la balise du Vaisseau depuis l\u0027intérieur de la graine, mais l\u0027ouverture était trop étroite pour un Nomaï, sans parler d\u0027une capsule de sauvetage."},{"id":"DB_NOMAI_GRAVE_X3","rumor":false,"order":144,"unread":false,"text":"La balise du Vaisseau se mourait, et ne tarderait pas à s\u0027éteindre complètement."},{"id":"DB_NOMAI_GRAVE_X4","rumor":false,"order":145,"unread":false,"text":"En envoyant mon guetteur à l\u0027intérieur de la graine, je peux prendre des photos d\u0027une gigantesque épave de vaisseau nomaï."}]},{"astro":"DARK_BRAMBLE","id":"DB_VESSEL","name":"Le Vaisseau","parent":null,"state":"more","firstOrder":34,"facts":[{"id":"DB_VESSEL_R3","rumor":true,"order":34,"unread":false,"text":"Le générateur de distorsion du Vaisseau se brisa lorsque le Vaisseau s\u0027écrasa sur Sombronces."},{"id":"DB_VESSEL_R4","rumor":true,"order":146,"unread":false,"text":"J\u0027ai envoyé mon guetteur à l\u0027intérieur de la graine retrouvée près de la tombe nomaï. J\u0027ai pu ainsi prendre des photos d\u0027une gigantesque épave de vaisseau nomaï."},{"id":"DB_VESSEL_X1","rumor":false,"order":147,"unread":false,"text":"J\u0027ai retrouvé l\u0027épave du Vaisseau nomaï dans les entrailles de Sombronces."},{"id":"DB_VESSEL_X3","rumor":false,"order":148,"unread":false,"text":"Sur le pont du Vaisseau, j\u0027ai activé un pilier trilatéral qui semblait être une sorte de dispositif de saisie."},{"id":"DB_VESSEL_X4","rumor":false,"order":149,"unread":false,"text":"Les Nomaï tentèrent d\u0027appeler à l\u0027aide, mais le système de communication du Vaisseau n\u0027avait pas résisté au crash."},{"id":"DB_VESSEL_X5","rumor":false,"order":150,"unread":false,"text":"Le Vaisseau peut toujours recevoir des messages provenant des autres vaisseaux nomaï. Les clans nomaï restants se rassemblent face à la mort imminente de l\u0027univers."},{"id":"DB_VESSEL_X6","rumor":false,"order":151,"unread":false,"text":"J\u0027ai trouvé un enregistrement du premier signal émis par l\u0027Œil de l\u0027univers que les Nomaï ont détecté. Comme les Nomaï craignaient que le signal ne disparaisse, ils sont passés en distorsion sans prendre le temps d\u0027informer un autre clan de leur destination."},{"id":"DB_VESSEL_R2","rumor":true,"order":195,"unread":false,"text":"Le Vaisseau s\u0027écrasa quelque part sur Sombronces."},{"id":"DB_VESSEL_R1","rumor":true,"order":198,"unread":false,"text":"Les Nomaï arrivèrent dans ce système solaire par distorsion à bord d\u0027un véhicule spatial appelé le Vaisseau. Ils tentaient de suivre un signal provenant de l\u0027Œil de l\u0027univers."}]},{"astro":"ORBITAL_PROBE_CANNON","id":"ORBITAL_PROBE_CANNON","name":"Lance-sondes orbital","parent":null,"state":"done","firstOrder":54,"facts":[{"id":"ORBITAL_PROBE_CANNON_R4","rumor":true,"order":54,"unread":false,"text":"Les Nomaï décidèrent de construire un lance-sondes en orbite autour de Léviathe."},{"id":"ORBITAL_PROBE_CANNON_R3","rumor":true,"order":60,"unread":false,"text":"Gabbro voit un flash lumineux dans le ciel au début de chaque boucle. Il doit se passer quelque chose en orbite de Léviathe."},{"id":"ORBITAL_PROBE_CANNON_R2","rumor":true,"order":71,"unread":false,"text":"J\u0027ai utilisé un bassin de projection nomaï et j\u0027ai vu l\u0027intérieur d\u0027une station spatiale en orbite autour de Léviathe."},{"id":"ORBITAL_PROBE_CANNON_R1","rumor":true,"order":76,"unread":false,"text":"Les Nomaï achevèrent la construction du dernier module pour le lance-sondes orbital et l\u0027envoyèrent en orbite autour de Léviathe."},{"id":"ORBITAL_PROBE_CANNON_X1","rumor":false,"order":157,"unread":false,"text":"Les vestiges d\u0027une station spatiale nomaï en orbite autour de Léviathe. Il existe trois voies d\u0027accès partant de la zone centrale."},{"id":"ORBITAL_PROBE_CANNON_X2","rumor":false,"order":162,"unread":false,"text":"Le lance-sondes orbital fut créé dans le but de trouver l\u0027emplacement exact de l\u0027Œil de l\u0027univers."},{"id":"ORBITAL_PROBE_CANNON_X3","rumor":false,"order":163,"unread":false,"text":"Les Nomaï poussèrent le lance-sondes orbital au-delà de ses paramètres de puissance maximale pour augmenter leurs chances de trouver l\u0027Œil de l\u0027univers."}]},{"astro":"ORBITAL_PROBE_CANNON","id":"OPC_SUNKEN_MODULE","name":"Module de pistage","parent":"ORBITAL_PROBE_CANNON","state":"done","firstOrder":158,"facts":[{"id":"OPC_SUNKEN_MODULE_R1","rumor":true,"order":158,"unread":false,"text":"L\u0027un des trois modules du lance-sondes orbital."},{"id":"OPC_SUNKEN_MODULE_R5","rumor":true,"order":166,"unread":false,"text":"Le module de pistage reçoit des données de la sonde lancée."},{"id":"OPC_SUNKEN_MODULE_R2","rumor":true,"order":169,"unread":false,"text":"Un ordinateur nomaï signale que le module de pistage a \"disparu\"."},{"id":"OPC_SUNKEN_MODULE_R4","rumor":true,"order":170,"unread":false,"text":"Un Nomaï se trouvant à bord du module de pistage serait le premier à connaître les coordonnées de l\u0027Œil de l\u0027univers."},{"id":"OPC_SUNKEN_MODULE_R3","rumor":true,"order":173,"unread":false,"text":"J\u0027ai vu le module de pistage à travers un bassin de projection nomaï. On dirait que le module est sous l\u0027eau. J\u0027ai vu de l\u0027électricité violette à l\u0027extérieur du hublot."},{"id":"OPC_SUNKEN_MODULE_X1","rumor":false,"order":174,"unread":false,"text":"Le lance-sondes orbital a propulsé des millions de sondes dans l\u0027espace."},{"id":"OPC_SUNKEN_MODULE_X2","rumor":false,"order":175,"unread":false,"text":"La sonde 9 318 054 a détecté une anomalie spatiale remplissant tous les critères connus relatifs à l\u0027Œil de l\u0027univers."},{"id":"OPC_EYE_COORDINATES_X1","rumor":false,"order":176,"unread":false,"text":"J\u0027ai trouvé des coordonnées nomaï indiquant la position de l\u0027Œil de l\u0027univers."},{"id":"OPC_SUNKEN_MODULE_X3","rumor":false,"order":177,"unread":false,"text":"Le module de pistage enregistre automatiquement la trajectoire de chaque sonde et transmet les données obtenues au projet Sablière noire."}]},{"astro":"ORBITAL_PROBE_CANNON","id":"OPC_BROKEN_MODULE","name":"Module de lancement","parent":"ORBITAL_PROBE_CANNON","state":"done","firstOrder":159,"facts":[{"id":"OPC_BROKEN_MODULE_R1","rumor":true,"order":159,"unread":false,"text":"L\u0027un des trois modules du lance-sondes orbital."},{"id":"OPC_BROKEN_MODULE_R2","rumor":true,"order":161,"unread":false,"text":"Le module de lancement a l\u0027air très endommagé. Le hublot présente une large fissure."},{"id":"OPC_BROKEN_MODULE_R3","rumor":true,"order":168,"unread":false,"text":"Le hublot du module de lancement est fracturé, ce qui l\u0027expose au vide spatial."},{"id":"OPC_BROKEN_MODULE_X1","rumor":false,"order":169,"unread":false,"text":"Le module de lancement a subi d\u0027importants dégâts, mais le bassin de projection est toujours intact."},{"id":"OPC_BROKEN_MODULE_X2","rumor":false,"order":171,"unread":false,"text":"Une Nomaï du nom de Mallow avança que ce ne serait pas grave si le lance-sondes subissait des dommages structurels, car la sonde ne serait tirée qu\u0027une seule fois."},{"id":"OPC_BROKEN_MODULE_X3","rumor":false,"order":172,"unread":false,"text":"Une Nomaï du nom de Privett objecta qu\u0027il serait impossible de recevoir des données de la sonde si le module de pistage venait à être détruit."}]},{"astro":"ORBITAL_PROBE_CANNON","id":"OPC_INTACT_MODULE","name":"Module de contrôle","parent":"ORBITAL_PROBE_CANNON","state":"done","firstOrder":160,"facts":[{"id":"OPC_INTACT_MODULE_R1","rumor":true,"order":160,"unread":false,"text":"L\u0027un des trois modules du lance-sondes orbital."},{"id":"OPC_INTACT_MODULE_X2","rumor":false,"order":165,"unread":false,"text":"La sonde fut lancée, mais l\u0027intégrité structurelle du lance-sondes fut compromise pendant l\u0027opération. Des dégâts sont détectés sur plusieurs modules."},{"id":"OPC_INTACT_MODULE_X1","rumor":false,"order":167,"unread":false,"text":"Le module de contrôle a (récemment) reçu une requête du projet Sablière noire demandant le lancement d\u0027une sonde. Le canon fut aligné sur une trajectoire de sonde choisie aléatoirement."}]},{"astro":"TIMBER_HEARTH","id":"TH_VILLAGE","name":"Village","parent":null,"state":"done","firstOrder":0,"facts":[{"id":"TH_VILLAGE_X1","rumor":false,"order":0,"unread":false,"text":"Le seul village âtrien qui existe, ainsi que la principale source d\u0027explosions sur cette planète."},{"id":"TH_VILLAGE_X2","rumor":false,"order":7,"unread":false,"text":"La statue nomaï à l\u0027observatoire a ouvert les yeux et a regardé dans ma direction ! J\u0027ai aperçu des lumières étranges et j\u0027ai vu mes propres souvenirs défiler devant mes yeux."},{"id":"TH_VILLAGE_X3","rumor":false,"order":8,"unread":false,"text":"Hal dit que la statue n\u0027a jamais ouvert les yeux auparavant (en dépit de tous les efforts de Cornée)."}]},{"astro":"TIMBER_HEARTH","id":"TH_ZERO_G_CAVE","name":"Grotte antigrav","parent":"TH_VILLAGE","state":"done","firstOrder":1,"facts":[{"id":"TH_ZERO_G_CAVE_R1","rumor":true,"order":1,"unread":false,"text":"J\u0027ai entendu dire que Gossan a préparé la grotte antigrav au cas où j\u0027aurais besoin d\u0027une piqûre de rappel avant de partir."},{"id":"TH_ZERO_G_CAVE_X1","rumor":false,"order":3,"unread":false,"text":"Une grotte située au cœur même d\u0027Âtrebois et utilisée dans le cadre du programme Odyssée pour l\u0027entraînement des nouveaux astronautes."},{"id":"TH_ZERO_G_CAVE_X2","rumor":false,"order":4,"unread":false,"text":"J\u0027ai réparé un autre \"satellite\" pour Gossan."}]},{"astro":"TIMBER_HEARTH","id":"TH_IMPACT_CRATER","name":"Graine de Sombronces","parent":null,"state":"done","firstOrder":14,"facts":[{"id":"TH_IMPACT_CRATER_R1","rumor":true,"order":14,"unread":false,"text":"Le journal de l\u0027onduloscope d\u0027Esker relève un air d\u0027harmonica en provenance d\u0027Âtrebois. À l\u0027en croire, il s\u0027agirait de l\u0027harmonica de Feldspath, mais Feldspath a disparu dans l\u0027espace il y a un bail."},{"id":"TH_IMPACT_CRATER_X1","rumor":false,"order":131,"unread":false,"text":"Une graine de Sombronces s\u0027est écrasée ici et a déjà pris racine. Tectite veut utiliser un lance-guetteur pour voir ce qu\u0027il y a à l\u0027intérieur."},{"id":"TH_IMPACT_CRATER_X3","rumor":false,"order":133,"unread":false,"text":"J\u0027ai lancé mon petit guetteur à l\u0027intérieur de la graine. Je ne sais pas pourquoi, mais la graine est bien plus grande à l\u0027intérieur."},{"id":"TH_IMPACT_CRATER_X2","rumor":false,"order":134,"unread":false,"text":"Mon onduloscope repère un air d\u0027harmonica quand je l\u0027oriente en direction de la graine."}]},{"astro":"TIMBER_HEARTH","id":"TH_NOMAI_MINE","name":"Mines nomaï","parent":null,"state":"more","firstOrder":127,"facts":[{"id":"TH_NOMAI_MINE_X1","rumor":false,"order":127,"unread":false,"text":"Les Nomaï exploitaient ce site pour en extraire du minerai destiné à fabriquer une enveloppe protectrice, conçue pour sceller physiquement la salle centrale, dans la Sablière noire."},{"id":"TH_NOMAI_MINE_X2","rumor":false,"order":128,"unread":false,"text":"Une fois l\u0027enveloppe terminée, les Nomaï s\u0027assurèrent qu\u0027il n\u0027y avait plus aucun passage ni fissure."}]},{"astro":"TIMBER_HEARTH","id":"TH_QUANTUM_SHARD","name":"Bois quantique","parent":null,"state":"more","firstOrder":40,"facts":[{"id":"TH_QUANTUM_SHARD_R2","rumor":true,"order":40,"unread":false,"text":"Les Nomaï détectèrent un signal quantique provenant de quelque part sur Âtrebois."},{"id":"TH_QUANTUM_SHARD_R1","rumor":true,"order":129,"unread":false,"text":"Chail a détecté un signal étrange en provenance du cratère situé au pôle Sud d\u0027Âtrebois. Il est très similaire à celui émis par la Lune quantique."},{"id":"TH_QUANTUM_SHARD_X2","rumor":false,"order":131,"unread":false,"text":"J\u0027ai trouvé un poème écrit sur l\u0027un des arbres de ce bois."}]},{"astro":"TIMBER_HEARTH","id":"TH_RADIO_TOWER","name":"Tour de transmission","parent":null,"state":"done","firstOrder":198,"facts":[{"id":"TH_RADIO_TOWER_X1","rumor":false,"order":198,"unread":false,"text":"Une tour de transmission conçue pour recevoir les photos prises par le satellite d\u0027espace lointain. Plusieurs photos du système solaire entier ornent les murs. Cornée a remarqué un détail étrange sur l\u0027une d\u0027elles, mais en a conclu que la seule explication rationnelle était une défaillance matérielle."}]},{"astro":"CAVE_TWIN","id":"CT_CHERT","name":"Campement de Chail","parent":null,"state":"more","firstOrder":91,"facts":[{"id":"CT_CHERT_X1","rumor":false,"order":91,"unread":false,"text":"Chail a installé son équipement d\u0027astronomie au pôle Nord de la Sablière rouge."},{"id":"CT_CHERT_X2","rumor":false,"order":92,"unread":false,"text":"Chail a repéré un nombre anormalement élevé de supernovæ ces derniers temps."}]},{"astro":"CAVE_TWIN","id":"CT_QUANTUM_MOON_LOCATOR","name":"Traceur lunaire","parent":null,"state":"done","firstOrder":112,"facts":[{"id":"CT_QUANTUM_MOON_LOCATOR_X2","rumor":false,"order":112,"unread":false,"text":"Les Nomaï avancèrent l\u0027hypothèse que la Lune quantique pouvait être une forme de mécanique quantique macroscopique."},{"id":"CT_QUANTUM_MOON_LOCATOR_X1","rumor":false,"order":113,"unread":false,"text":"Un appareil nomaï créé pour localiser la Lune quantique."},{"id":"CT_QUANTUM_MOON_LOCATOR_X3","rumor":false,"order":114,"unread":false,"text":"La Lune quantique visite un total de cinq lieux."}]},{"astro":"CAVE_TWIN","id":"CT_GRAVITY_CANNON","name":"Canon gravitationnel","parent":null,"state":"done","firstOrder":83,"facts":[{"id":"CT_GRAVITY_CANNON_X2","rumor":false,"order":83,"unread":false,"text":"J\u0027ai rappelé une navette nomaï de l\u0027Intrus."},{"id":"CT_GRAVITY_CANNON_X1","rumor":false,"order":89,"unread":false,"text":"Une gigantesque structure cylindrique qui génère un puissant champ gravitationnel vertical."}]},{"astro":"CAVE_TWIN","id":"CT_ESCAPE_POD","name":"Capsule de sauvetage 2","parent":null,"state":"done","firstOrder":93,"facts":[{"id":"CT_ESCAPE_POD_R2","rumor":true,"order":93,"unread":false,"text":"Chail a vu une épave nomaï projeter un rayon lumineux vers le ciel quelque part au pôle Sud de la Sablière rouge."},{"id":"CT_ESCAPE_POD_X1","rumor":false,"order":97,"unread":false,"text":"L\u0027une des trois capsules de sauvetage nomaï qui s\u0027écrasèrent dans notre système solaire."},{"id":"CT_ESCAPE_POD_X2","rumor":false,"order":98,"unread":false,"text":"Ces trois capsules de sauvetage provenaient d\u0027une chose appelée le Vaisseau, qui avait subi d\u0027importants dégâts."},{"id":"CT_ESCAPE_POD_R1","rumor":true,"order":192,"unread":false,"text":"L\u0027une des trois capsules de sauvetage nomaï atterrit quelque part sur les Sablières."}]},{"astro":"CAVE_TWIN","id":"CT_HIGH_ENERGY_LAB","name":"Laboratoire des hautes énergies","parent":null,"state":"more","firstOrder":115,"facts":[{"id":"CT_HIGH_ENERGY_LAB_X2","rumor":false,"order":115,"unread":false,"text":"Les Nomaï découvrirent qu\u0027ils pouvaient augmenter l\u0027intervalle de temps négatif entre l\u0027arrivée et le départ d\u0027un objet en ajoutant de l\u0027énergie aux générateurs de distorsion."},{"id":"CT_HIGH_ENERGY_LAB_X3","rumor":false,"order":117,"unread":false,"text":"Les Nomaï voulaient savoir s\u0027il était possible d\u0027atteindre un intervalle de temps négatif de 22 minutes. Ils constatèrent qu\u0027ils auraient besoin d\u0027une technologie supérieure pour produire l\u0027énergie nécessaire ainsi que d\u0027un générateur de distorsion avancé capable de gérer une telle quantité d\u0027énergie. Il fut suggéré que le projet serait réalisé sur la Sablière noire."},{"id":"CT_HIGH_ENERGY_LAB_R3","rumor":true,"order":123,"unread":false,"text":"Il n\u0027est possible d\u0027accéder au laboratoire des hautes énergies qu\u0027en empruntant un chemin partant de la Cité obscure."},{"id":"CT_HIGH_ENERGY_LAB_R2","rumor":true,"order":124,"unread":false,"text":"C\u0027est au laboratoire des hautes énergies que le projet Sablière noire vit le jour. Il s\u0027agit d\u0027un bâtiment doté de grands panneaux solaires situé sur l\u0027équateur de la Sablière rouge."},{"id":"CT_HIGH_ENERGY_LAB_R1","rumor":true,"order":126,"unread":false,"text":"L\u0027intervalle de temps négatif mesuré à la station du trou blanc fit l\u0027objet d\u0027études supplémentaires au laboratoire des hautes énergies (dans le canyon sur l\u0027équateur de la Sablière rouge)."}]},{"astro":"CAVE_TWIN","id":"CT_WARP_TOWER_MAP","name":"Plans des tours de la Sablière noire","parent":"CT_HIGH_ENERGY_LAB","state":"done","firstOrder":118,"facts":[{"id":"CT_WARP_TOWER_MAP_X1","rumor":false,"order":118,"unread":false,"text":"Plans des tours sur l\u0027équateur de la Sablière noire."},{"id":"CT_WARP_TOWER_MAP_X2","rumor":false,"order":119,"unread":false,"text":"Ces tours permirent aux Nomaï de voyager rapidement entre la Sablière noire et les autres lieux essentiels à la réalisation du projet Sablière noire."},{"id":"CT_WARP_TOWER_MAP_X4","rumor":false,"order":120,"unread":false,"text":"Chaque tour mène à une planète différente (même si de nombreux Nomaï ont vite remarqué que le soleil n\u0027est en fait pas une planète)."},{"id":"CT_WARP_TOWER_MAP_X3","rumor":false,"order":121,"unread":false,"text":"L\u0027apparence de chaque tour évoque sa destination."}]},{"astro":"CAVE_TWIN","id":"CT_SUNLESS_CITY","name":"Cité obscure","parent":null,"state":"more","firstOrder":84,"facts":[{"id":"CT_SUNLESS_CITY_R2","rumor":true,"order":84,"unread":false,"text":"J\u0027ai trouvé un repère indiquant une piste menant à la Cité obscure, mais la voie est bloquée."},{"id":"CT_SUNLESS_CITY_R4","rumor":true,"order":94,"unread":false,"text":"Selon Chail, l\u0027absence de ruines en surface vient du fait que les Nomaï ont dû vivre quelque part sous la terre."},{"id":"CT_SUNLESS_CITY_R3","rumor":true,"order":95,"unread":false,"text":"Les Nomaï découvrirent un lieu susceptible de constituer un refuge à long terme au bout de l\u0027un des passages qui s\u0027étendaient sous la capsule de sauvetage."},{"id":"CT_SUNLESS_CITY_R1","rumor":true,"order":96,"unread":false,"text":"Les survivants Nomaï échoués sur la Sablière rouge décidèrent de chercher refuge dans les grottes situées sous leur capsule de sauvetage."},{"id":"CT_SUNLESS_CITY_X1","rumor":false,"order":100,"unread":false,"text":"Une cité nomaï nichée au creux des parois d\u0027une immense caverne souterraine. La cité est construite selon une structure verticale et se compose de quatre secteurs."},{"id":"CT_SUNLESS_CITY_X2","rumor":false,"order":106,"unread":false,"text":"Les Nomaï débattirent de l\u0027utilité de construire une station solaire pour alimenter le projet Sablière noire. De nombreux Nomaï s\u0027opposèrent à cette idée en avançant qu\u0027un échec pourrait causer la destruction du système solaire."},{"id":"CT_SUNLESS_CITY_R5","rumor":true,"order":124,"unread":false,"text":"Il est possible d\u0027accéder au laboratoire des hautes énergies en empruntant un chemin partant de la Cité obscure."}]},{"astro":"CAVE_TWIN","id":"CT_ANGLERFISH_FOSSIL","name":"Fossile de cœlacanthe","parent":null,"state":"done","firstOrder":35,"facts":[{"id":"CT_ANGLERFISH_FOSSIL_R2","rumor":true,"order":35,"unread":false,"text":"Les Nomaï apprirent comment échapper au cœlacanthe (du moins en théorie) en étudiant un fossile de cœlacanthe retrouvé sur la Sablière rouge."},{"id":"CT_ANGLERFISH_FOSSIL_R1","rumor":true,"order":99,"unread":false,"text":"J\u0027ai trouvé une grotte abritant un fossile de cœlacanthe, mais l\u0027entrée est si étroite que seul mon guetteur peut s\u0027y faufiler."},{"id":"CT_ANGLERFISH_FOSSIL_R3","rumor":true,"order":107,"unread":false,"text":"Les enfants nomaï jouaient à un jeu dans la grotte du cœlacanthe. Il est possible d\u0027accéder à la grotte du cœlacanthe depuis la caverne au gué."},{"id":"CT_ANGLERFISH_FOSSIL_X1","rumor":false,"order":108,"unread":false,"text":"Les enfants nomaï jouaient à un jeu ici. L\u0027un d\u0027eux était le cœlacanthe et portait un bandeau. Les autres (les poissons) s\u0027alignaient contre un mur. Quand le cœlacanthe disait \"Partez !\", les poissons devaient se faufiler de l\u0027autre côté."},{"id":"CT_ANGLERFISH_FOSSIL_R4","rumor":true,"order":108,"unread":false,"text":"L\u0027accès depuis la caverne au gué est difficile à distinguer sauf si l\u0027on donne d\u0027abord une lanterne au cœlacanthe."},{"id":"CT_ANGLERFISH_FOSSIL_X2","rumor":false,"order":109,"unread":false,"text":"La règle du bandeau fut ajoutée car les vrais cœlacanthes sont aveugles."},{"id":"CT_ANGLERFISH_FOSSIL_X3","rumor":false,"order":110,"unread":false,"text":"Les Nomaï adultes étaient ravis de voir les enfants intégrer le fruit de leurs recherches aux règles du jeu."}]},{"astro":"CAVE_TWIN","id":"CT_QUANTUM_CAVES","name":"Grottes quantiques","parent":null,"state":"more","firstOrder":39,"facts":[{"id":"CT_QUANTUM_CAVES_R1","rumor":true,"order":39,"unread":false,"text":"Les Nomaï détectèrent un signal quantique en provenance des Sablières."},{"id":"CT_QUANTUM_CAVES_X1","rumor":false,"order":90,"unread":false,"text":"Les Nomaï constatèrent la présence d\u0027un étrange roc errant visible dans plusieurs grottes du pôle Nord de la Sablière rouge."}]},{"astro":"CAVE_TWIN","id":"CT_LAKEBED_CAVERN","name":"Grotte asséchée","parent":null,"state":"rumor","firstOrder":89,"facts":[{"id":"CT_LAKEBED_CAVERN_R2","rumor":true,"order":89,"unread":false,"text":"Un Nomaï du nom de Coleus disparut mystérieusement dans une grotte située au fond du lit du lac asséché, au pôle Nord de la Sablière rouge."},{"id":"CT_LAKEBED_CAVERN_R1","rumor":true,"order":115,"unread":false,"text":"Le roc errant fut aperçu pour la première fois dans une grotte située au fond du lit du lac asséché, au pôle Nord de la Sablière rouge."}]},{"astro":"SUN_STATION","id":"S_SUNSTATION","name":"Station solaire","parent":null,"state":"rumor","firstOrder":101,"facts":[{"id":"S_SUNSTATION_R3","rumor":true,"order":101,"unread":false,"text":"Les Nomaï construisirent une structure appelée la station solaire, mais cette décision ne fit pas l\u0027unanimité parmi eux."},{"id":"S_SUNSTATION_R2","rumor":true,"order":105,"unread":false,"text":"Les Nomaï débattirent de l\u0027utilité de construire une station solaire pour alimenter le projet Sablière noire."}]},{"astro":"TIMBER_MOON","id":"TM_ESKER","name":"Campement d\u0027Esker","parent":null,"state":"done","firstOrder":2,"facts":[{"id":"TM_ESKER_R1","rumor":true,"order":2,"unread":false,"text":"On dirait qu\u0027Esker se trouve toujours sur Rocaille. Ça fait déjà un moment."},{"id":"TM_ESKER_X1","rumor":false,"order":12,"unread":false,"text":"Esker fait pousser des arbres dans son campement. Tout a l\u0027air d\u0027aller bien, mais il y a fort à parier que la solitude commence à lui peser."}]},{"astro":"TIMBER_MOON","id":"TM_NORTH_POLE","name":"Poste d\u0027observation lunaire","parent":null,"state":"done","firstOrder":13,"facts":[{"id":"TM_NORTH_POLE_R1","rumor":true,"order":13,"unread":false,"text":"Esker dit que le pôle Nord de Rocaille (indiqué en rouge sur ma mini-carte) est l\u0027endroit idéal pour écouter la musique des autres voyageurs avec un onduloscope."},{"id":"TM_NORTH_POLE_X1","rumor":false,"order":15,"unread":false,"text":"Un poste d\u0027observation offrant une vue imprenable sur le système solaire. Esker se sert de son onduloscope pour surveiller la position des autres voyageurs."}]},{"astro":"TIMBER_MOON","id":"TM_EYE_LOCATOR","name":"Traceur oculaire","parent":null,"state":"done","firstOrder":6,"facts":[{"id":"TM_EYE_LOCATOR_R2","rumor":true,"order":6,"unread":false,"text":"Le texte nomaï dans l\u0027observatoire évoque le calibrage d\u0027une sorte d\u0027appareil sur Rocaille."},{"id":"TM_EYE_LOCATOR_R1","rumor":true,"order":7,"unread":false,"text":"J\u0027ai entendu dire qu\u0027il y avait des ruines nomaï quelque part sur Rocaille. Personne ne sait à quoi elles servaient ni pourquoi elles ont été construites."},{"id":"TM_EYE_LOCATOR_X1","rumor":false,"order":8,"unread":false,"text":"Un appareil nomaï conçu pour localiser les sources de signaux lointains."},{"id":"TM_EYE_LOCATOR_X2","rumor":false,"order":9,"unread":false,"text":"Les Nomaï furent dépités de ne pas parvenir à détecter un signal provenant d\u0027une entité appelée l\u0027Œil de l\u0027univers."}]},{"astro":"TOWER_TWIN","id":"TT_WARP_TOWERS","name":"Tours de la Sablière noire","parent":null,"state":"done","firstOrder":102,"facts":[{"id":"TT_WARP_TOWERS_X1","rumor":false,"order":102,"unread":false,"text":"Plusieurs tours nomaï imposantes forment un anneau autour de l\u0027équateur de la Sablière noire."},{"id":"TT_WARP_TOWERS_X2","rumor":false,"order":105,"unread":false,"text":"La station du trou blanc servit de modèle pour ces tours, construites dans le cadre du projet Sablière noire."}]},{"astro":"TOWER_TWIN","id":"TT_TIME_LOOP_DEVICE","name":"Projet Sablière noire","parent":null,"state":"done","firstOrder":77,"facts":[{"id":"TT_TIME_LOOP_DEVICE_R3","rumor":true,"order":77,"unread":false,"text":"Chaque souvenir enregistré par une statue nomaï est transmis à l\u0027unité de stockage correspondante sur la Sablière noire."},{"id":"TT_TIME_LOOP_DEVICE_R2","rumor":true,"order":116,"unread":false,"text":"Les Nomaï voulaient concevoir une technologie capable de générer un intervalle de temps négatif de 22 minutes sur la Sablière noire."},{"id":"TT_TIME_LOOP_DEVICE_R1","rumor":true,"order":126,"unread":false,"text":"La salle centrale dans la Sablière noire a été scellée physiquement par une enveloppe protectrice incroyablement épaisse."},{"id":"TT_TIME_LOOP_DEVICE_X1","rumor":false,"order":134,"unread":false,"text":"Une cavité creusée à l\u0027intérieur de la Sablière noire. Les câbles d\u0027énergie à la surface sont connectés à une enveloppe protectrice au centre de la planète."},{"id":"TT_TIME_LOOP_DEVICE_X2","rumor":false,"order":135,"unread":false,"text":"Il y a huit monolithes auxquels sont fixés des masques nomaï. Parmi ces masques, trois reçoivent des données provenant respectivement du module de pistage, de Léviathe et d\u0027Âtrebois."},{"id":"TT_TIME_LOOP_DEVICE_X3","rumor":false,"order":136,"unread":false,"text":"Le projet Sablière noire visait à tirer parti de l\u0027énergie générée par une supernova (obtenue au moyen de la station solaire) afin d\u0027envoyer les données de la sonde issue du lance-sondes orbital 22 minutes dans le passé."},{"id":"TT_TIME_LOOP_DEVICE_X4","rumor":false,"order":137,"unread":false,"text":"La station solaire n\u0027a pas fonctionné. Bien que le projet Sablière noire fût théoriquement viable, les Nomaï ne parvinrent pas à l\u0027alimenter."},{"id":"TT_TIME_LOOP_DEVICE_X5","rumor":false,"order":138,"unread":false,"text":"Il y a un générateur de distorsion avancé à l\u0027intérieur de l\u0027enveloppe protectrice au centre de la planète. Retirer le générateur désactivera le projet Sablière noire."}]},{"astro":"COMET","id":"COMET_SHUTTLE","name":"Navette nomaï gelée","parent":null,"state":"more","firstOrder":85,"facts":[{"id":"COMET_SHUTTLE_X2","rumor":false,"order":85,"unread":false,"text":"Les Nomaï atterrirent sur l\u0027Intrus peu après son arrivée dans le système solaire. Les instruments de la navette entendirent des relevés d\u0027énergie étranges provenant de sous la surface."},{"id":"COMET_SHUTTLE_X4","rumor":false,"order":88,"unread":false,"text":"Clary, la Nomaï restée en arrière, perdit contact avec ses compagnons après qu\u0027ils fussent descendus sous la surface de l\u0027Intrus."}]},{"astro":"COMET","id":"COMET_INTERIOR","name":"Noyau rompu","parent":null,"state":"done","firstOrder":86,"facts":[{"id":"COMET_INTERIOR_R1","rumor":true,"order":86,"unread":false,"text":"Les instruments de la navette entendirent des relevés d\u0027énergie étranges provenant de sous la surface."},{"id":"COMET_INTERIOR_R2","rumor":true,"order":87,"unread":false,"text":"Deux des Nomaï repérèrent une fissure dans la glace, sur la face ensoleillée de l\u0027Intrus. Ils s\u0027y engagèrent pour voir ce qu\u0027il s\u0027y trouvait."},{"id":"COMET_INTERIOR_X2","rumor":false,"order":177,"unread":false,"text":"Les Nomaï suivirent la piste des relevés d\u0027énergie jusqu\u0027à atteindre une enveloppe rocheuse de forme sphérique contenant une matière inconnue."},{"id":"COMET_INTERIOR_X1","rumor":false,"order":177,"unread":false,"text":"J\u0027ai retrouvé les deux membres disparus de l\u0027équipage de la navette nomaï près d\u0027un rocher brisé qui semblait avoir implosé."},{"id":"COMET_INTERIOR_X3","rumor":false,"order":178,"unread":false,"text":"Ils constatèrent que cette étrange matière était mortelle et soumise à une très forte pression. Si la pierre venait à céder, la matière étrange qu\u0027elle renfermait se répandrait à une telle vitesse qu\u0027elle engloutirait le système solaire tout entier en un instant."},{"id":"COMET_INTERIOR_X4","rumor":false,"order":179,"unread":false,"text":"L\u0027un des Nomaï resta sur place pour étudier la xénomatière. Son compagnon s\u0027empressa de remonter sur la surface pour avertir les autres Nomaï."}]},{"astro":"QUANTUM_MOON","id":"QUANTUM_MOON","name":"Lune quantique","parent":null,"state":"done","firstOrder":30,"facts":[{"id":"QUANTUM_MOON_R1","rumor":true,"order":30,"unread":false,"text":"Les Nomaï sur Cravité constatèrent l\u0027existence d\u0027une Lune fantôme qui apparaissait parfois dans le ciel."},{"id":"QUANTUM_MOON_R3","rumor":true,"order":43,"unread":false,"text":"Une Nomaï du nom de Solanum s\u0027est rendue sur la Lune quantique à bord d\u0027une navette."},{"id":"QUANTUM_MOON_R2","rumor":true,"order":111,"unread":false,"text":"Les Nomaï sur la Sablière rouge remarquèrent la présence d\u0027une lune qui disparaissait parfois quand personne ne l\u0027observait."},{"id":"QUANTUM_MOON_R4","rumor":true,"order":130,"unread":false,"text":"Les notes de Chail évoquent une Lune quantique sur laquelle aucun Âtrien n\u0027a encore réussi à atterrir."},{"id":"QUANTUM_MOON_X2","rumor":false,"order":179,"unread":false,"text":"J\u0027ai trouvé un Nomaï décédé dans une combinaison d\u0027astronaute, près du pôle Sud."},{"id":"QUANTUM_MOON_X1","rumor":false,"order":179,"unread":false,"text":"J\u0027ai réussi à atterrir sur la surface de la Lune quantique."}]},{"astro":"QUANTUM_MOON","id":"QM_SHUTTLE","name":"Navette de Solanum","parent":"QUANTUM_MOON","state":"done","firstOrder":44,"facts":[{"id":"QM_SHUTTLE_X1","rumor":false,"order":44,"unread":false,"text":"Une Nomaï du nom de Solanum vint sur la Lune quantique à bord d\u0027une navette et atterrit au pôle Sud. Elle se préparait à effectuer le reste de son voyage à pied."},{"id":"QM_SHUTTLE_X2","rumor":false,"order":45,"unread":false,"text":"Les individus se rendant sur la Lune quantique arrivent toujours au pôle Sud (pour une raison qui échappait aux Nomaï)."}]},{"astro":"QUANTUM_MOON","id":"QM_SHRINE","name":"Autel quantique","parent":"QUANTUM_MOON","state":"done","firstOrder":180,"facts":[{"id":"QM_SHRINE_X1","rumor":false,"order":180,"unread":false,"text":"Un autel nomaï errant sur la Lune quantique."},{"id":"QM_SHRINE_X4","rumor":false,"order":181,"unread":false,"text":"\"Souvenez-vous de la règle du sixième emplacement.\" : voilà ce qui est écrit à côté d\u0027une peinture murale représentant une tour suspendue au-dessus d\u0027un trou noir."},{"id":"QM_SHRINE_X2","rumor":false,"order":182,"unread":false,"text":"\"Vous vous êtes souvenu de la règle de l\u0027imagerie quantique.\" : voilà ce qui est écrit à côté d\u0027une peinture murale représentant une tour sur une île."},{"id":"QM_SHRINE_X3","rumor":false,"order":183,"unread":false,"text":"\"Souvenez-vous de la règle de l\u0027intrication quantique.\" : voilà ce qui est écrit à côté d\u0027une peinture murale représentant un roc quantique dans une grotte."},{"id":"QM_SHRINE_R1","rumor":true,"order":203,"unread":false,"text":"Les Nomaï édifièrent un autel sur la Lune quantique afin d\u0027aider les pèlerins à atteindre son sixième emplacement."}]},{"astro":"QUANTUM_MOON","id":"QM_SIXTH_LOCATION","name":"Sixième emplacement","parent":"QUANTUM_MOON","state":"done","firstOrder":115,"facts":[{"id":"QM_SIXTH_LOCATION_R1","rumor":true,"order":115,"unread":false,"text":"Parfois, la Lune quantique disparaît, peut-être pour se rendre à un sixième emplacement inconnu."},{"id":"QM_SIXTH_LOCATION_R2","rumor":true,"order":201,"unread":false,"text":"De nombreux Nomaï effectuèrent un pèlerinage au cours duquel la Lune quantique les amena à son sixième emplacement, le plus secret de tous."},{"id":"QM_SIXTH_LOCATION_R3","rumor":true,"order":202,"unread":false,"text":"Pour qu\u0027il soit possible d\u0027accéder au sixième emplacement, l\u0027autel sur la Lune quantique doit se trouver au pôle Nord de la lune."},{"id":"QM_SIXTH_LOCATION_X1","rumor":false,"order":204,"unread":false,"text":"J\u0027ai rencontré une Nomaï encore en vie du nom de Solanum au pôle Sud !"},{"id":"QM_SIXTH_LOCATION_X2","rumor":false,"order":205,"unread":false,"text":"Solanum se demande ce qu\u0027il adviendrait si un observateur conscient entrait dans l\u0027Œil lui-même."},{"id":"QM_SIXTH_LOCATION_X6","rumor":false,"order":206,"unread":false,"text":"Solanum a imaginé une hypothèse selon laquelle elle ne serait pas complètement en vie."},{"id":"QM_SIXTH_LOCATION_X5","rumor":false,"order":207,"unread":false,"text":"À cet emplacement, la Lune quantique devient un reflet de l\u0027Œil lui-même."},{"id":"QM_SIXTH_LOCATION_X4","rumor":false,"order":208,"unread":false,"text":"Il est probable que l\u0027Œil soit la source de tous les phénomènes quantiques macroscopiques de ce système solaire."},{"id":"QM_SIXTH_LOCATION_X3","rumor":false,"order":209,"unread":false,"text":"La Lune quantique est la lune de l\u0027Œil de l\u0027univers."}]},{"astro":"GIANTS_DEEP","id":"GD_OCEAN","name":"Abysses","parent":null,"state":"done","firstOrder":61,"facts":[{"id":"GD_OCEAN_R1","rumor":true,"order":61,"unread":false,"text":"Gabbro dit qu\u0027il y a un courant très fort un peu plus loin sous la surface de l\u0027océan qui empêche quoi que ce soit de s\u0027enfoncer plus profond."},{"id":"GD_OCEAN_R3","rumor":true,"order":64,"unread":false,"text":"Feldspath a trouvé un moyen d\u0027atteindre le cœur de Léviathe."},{"id":"GD_OCEAN_R2","rumor":true,"order":72,"unread":false,"text":"Les Nomaï sur le site de construction ont vu quelque chose s\u0027enfoncer sous le courant, ce qu\u0027ils tenaient jusqu\u0027alors pour impossible."},{"id":"GD_OCEAN_X1","rumor":false,"order":77,"unread":false,"text":"L\u0027océan est étonnamment calme sous le courant. Il y a une espèce de champ électrique autour du cœur de la planète."},{"id":"GD_OCEAN_X2","rumor":false,"order":173,"unread":false,"text":"J\u0027ai franchi la barrière électrique pour atteindre la forêt de corail, au cœur de la planète."}]},{"astro":"GIANTS_DEEP","id":"GD_GABBRO_ISLAND","name":"Île de Gabbro","parent":null,"state":"done","firstOrder":5,"facts":[{"id":"GD_GABBRO_ISLAND_R1","rumor":true,"order":5,"unread":false,"text":"Hal dit que Gabbro a voulu retourner sur Léviathe pour en apprendre plus au sujet de la statue nomaï dans l\u0027observatoire."},{"id":"GD_GABBRO_ISLAND_X0","rumor":false,"order":54,"unread":false,"text":"Gabbro se prélasse dans un hamac près du rivage de l\u0027île."},{"id":"GD_GABBRO_ISLAND_X3","rumor":false,"order":55,"unread":false,"text":"Apparemment, Gabbro et moi sommes les seuls à être conscients que nous nous trouvons dans une boucle temporelle."},{"id":"GD_GABBRO_ISLAND_X1","rumor":false,"order":57,"unread":false,"text":"Gabbro a trouvé une statue nomaï sur une autre île. Les yeux de la statue se sont mis à briller et Gabbro a vu ses souvenirs défiler devant ses yeux."},{"id":"GD_GABBRO_ISLAND_X2","rumor":false,"order":58,"unread":false,"text":"Gabbro se rappelle avoir vécu sa propre mort. Gabbro a vu ses souvenirs défiler devant ses yeux, exactement comme avec la statue."}]},{"astro":"GIANTS_DEEP","id":"GD_CONSTRUCTION_YARD","name":"Site de construction","parent":null,"state":"done","firstOrder":69,"facts":[{"id":"GD_CONSTRUCTION_YARD_X2","rumor":false,"order":69,"unread":false,"text":"Curieusement, les Nomaï suspendirent l\u0027utilisation du lance-sondes orbital pour une durée indéterminée. Le lande-sondes ne devait pas faire feu."},{"id":"GD_CONSTRUCTION_YARD_X3","rumor":false,"order":70,"unread":false,"text":"Selon un ordinateur nomaï, une sonde à longue portée a récemment été propulsée dans l\u0027espace à l\u0027aide du lance-sondes orbital."},{"id":"GD_CONSTRUCTION_YARD_X1","rumor":false,"order":75,"unread":false,"text":"C\u0027est sur cette île que les Nomaï construisirent le lance-sondes orbital."},{"id":"GD_CONSTRUCTION_YARD_R1","rumor":true,"order":164,"unread":false,"text":"Les Nomaï construisirent le lance-sondes orbital sur le site de construction de Léviathe."}]},{"astro":"GIANTS_DEEP","id":"GD_BRAMBLE_ISLAND","name":"Île des ronces","parent":null,"state":"done","firstOrder":62,"facts":[{"id":"GD_BRAMBLE_ISLAND_X1","rumor":false,"order":62,"unread":false,"text":"Une île sillonnée de plantes épineuses où l\u0027on peut voir ce qui ressemble à une méduse congelée. On dirait que Feldspath a bivouaqué ici avant de partir pour Sombronces."}]},{"astro":"GIANTS_DEEP","id":"GD_STATUE_ISLAND","name":"Île de la statue","parent":null,"state":"done","firstOrder":56,"facts":[{"id":"GD_STATUE_ISLAND_R1","rumor":true,"order":56,"unread":false,"text":"Il y a une statue nomaï sur la plage d\u0027une des îles de Léviathe. Elle est identique à celle que Gabbro a ramenée d\u0027Âtrebois."},{"id":"GD_STATUE_ISLAND_R2","rumor":true,"order":59,"unread":false,"text":"L\u0027Île de la statue (c\u0027est le nom que lui a donné Gabbro) est formée de deux îles reliées par une sorte d\u0027arche naturelle en pierre."},{"id":"GD_STATUE_ISLAND_X1","rumor":false,"order":65,"unread":false,"text":"Ce doit être sur cette île que les Nomaï ont réalisé des statues comme celle qui se trouve dans notre observatoire."},{"id":"GD_STATUE_ISLAND_X2","rumor":false,"order":69,"unread":false,"text":"J\u0027ai trouvé une statue nomaï sur la plage. Elle est identique à celle qui se trouve dans notre observatoire."}]},{"astro":"GIANTS_DEEP","id":"GD_STATUE_WORKSHOP","name":"Atelier des statues","parent":"GD_STATUE_ISLAND","state":"done","firstOrder":66,"facts":[{"id":"GD_STATUE_WORKSHOP_R2","rumor":true,"order":66,"unread":false,"text":"Certains enfants nomaï envisageaient de contourner la porte de l\u0027atelier des statues et de se faufiler à l\u0027intérieur en empruntant un autre chemin (plus dangereux)."},{"id":"GD_STATUE_WORKSHOP_R3","rumor":true,"order":67,"unread":false,"text":"J\u0027aperçois une grotte imposante depuis l\u0027une des ruines au sommet de l\u0027île. Le fond de la grotte est rempli d\u0027eau."},{"id":"GD_STATUE_WORKSHOP_R1","rumor":true,"order":68,"unread":false,"text":"J\u0027ai trouvé une enseigne comportant l\u0027inscription \"Atelier des statues\" à côté d\u0027une porte brisée qui permettait d\u0027accéder à l\u0027intérieur de l\u0027île."},{"id":"GD_STATUE_WORKSHOP_X1","rumor":false,"order":78,"unread":false,"text":"Les statues nomaï furent conçues pour se lier à un utilisateur unique et enregistrer ses souvenirs avant de les envoyer à une unité de stockage au sein du projet Sablière noire."},{"id":"GD_STATUE_WORKSHOP_X2","rumor":false,"order":79,"unread":false,"text":"Chaque unité de stockage à l\u0027intérieur du projet Sablière noire était pourvue d\u0027un masque (le pendant de la statue) capable de renvoyer les souvenirs ainsi stockés à l\u0027utilisateur auquel ils appartenaient."},{"id":"GD_STATUE_WORKSHOP_X3","rumor":false,"order":80,"unread":false,"text":"Les statues furent conçues pour s\u0027activer uniquement à la réussite du projet Sablière noire, ou s\u0027il venait à échouer."}]},{"astro":"GIANTS_DEEP","id":"GD_QUANTUM_TOWER","name":"Tour des épreuves quantiques","parent":null,"state":"done","firstOrder":41,"facts":[{"id":"GD_QUANTUM_TOWER_R1","rumor":true,"order":41,"unread":false,"text":"Les Nomaï détectèrent un signal quantique provenant de quelque part sur Léviathe."},{"id":"GD_QUANTUM_TOWER_X1","rumor":false,"order":80,"unread":false,"text":"Cette tour détenait le savoir nécessaire aux Nomaï devant entreprendre leur premier voyage quantique."},{"id":"GD_QUANTUM_TOWER_X2","rumor":false,"order":81,"unread":false,"text":"\"Observer un objet quantique. Observer l\u0027image d\u0027un objet quantique. Il n\u0027y a là aucune différence.\""},{"id":"GD_QUANTUM_TOWER_X3","rumor":false,"order":82,"unread":false,"text":"C\u0027est ce que les Nomaï appelaient la \"règle de l\u0027imagerie quantique\"."},{"id":"GD_QUANTUM_TOWER_X4","rumor":false,"order":83,"unread":false,"text":"\"Souvenez-vous, les autres rocs quantiques renferment d\u0027autres savoirs.\""}]}]};
